INSERT INTO dump_descriptions (base_key, description) VALUES ('backup_fsd-windowsnoeditoru39去除霰射吐株、荆棘丛、脓毒粒子', 'Strips multiple enemy and hazard particle effects, including Barrage Infector, Lobber, Bramble, and Exploding Goo Plant effects.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fsd-windowsnoeditoru39去机炮特效_p', 'Removes Autocannon particle effects, including casing, shot impact, first/third-person muzzle flashes, Mortar Barrage explosions, and Carpet Bomber effects.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('fsd-windowsnoeditoru39去火箭特效_p', 'Removes Micro Missile Launcher particle effects, including muzzle, exhaust, trails, impacts, cluster separation, and Butcher Rounds visuals.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('remove_hotglowandscorchedearth_p', 'Disables a broad set of decal materials, including Hot Glow and Scorched Earth, as well as blood splats, bullet impacts, and dwarf footprints.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('remove_scorchedearthonly_p', 'Disables Scorched Earth and many other decal materials, including blood splats, bullet impacts, puddles, and dwarf footprints.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('去除所有脚印，虫子血迹和子弹弹孔以提高帧数_p', 'Disables many decal materials, including dwarf footprints, bug blood splats, and bullet impacts; it also removes several fire, corrosion, and puddle decals.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('misccull6', 'Shortens draw distances for many cave hazards, collectibles, and enemy puddles; also dims Gold Chunk glow and shortens Sentinel Goo puddle lifetime.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('powerperks', 'Rebalances numerous perks, including stronger See You in Hell and Shield Boost effects, wider Beast Master interaction range, and changes to other perk bonuses.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('engineeroverhaullok1only', 'Rebalances only the LOK-1, with faster and longer-range locks, higher base damage, and revised lock-based upgrades and overclocks.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('itchyarserevival', 'Adds custom voice lines for Bosco revives, dwarves thanking a rescuer, and Iron Will activation.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('dea_a01_jpg', 'Adds custom enemy variants, including Glasher, colored and stagger spitters, several shooters, Trundle, Grooter, and Fanatic types.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('rc_m1000_battlerifle_p', 'Supplies a Rogue Core Battle Rifle model, weapon assets, first- and third-person animations, and firing/reload sounds.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
